      briefReview:
        "Você aprendeu que o adjetivo em espanhol concorda em gênero e número com o substantivo e geralmente vem DEPOIS dele (un coche rojo). Para comparar use 'más + adj + que' (mais que), 'menos + adj + que' (menos que) e 'tan + adj + como' (tão quanto). Irregulares: bueno → mejor, malo → peor.",
      briefReviewEn:
        "You learned that adjectives in Spanish agree in gender and number with the noun and usually come AFTER it (un coche rojo). To compare use 'más + adj + que' (more than), 'menos + adj + que' (less than) and 'tan + adj + como' (as ... as). Irregulars: bueno → mejor, malo → peor.",
