      briefReview: "Verbos reflexivos exigem pronomes: me/te/se/nos/os/se. Usados em rotinas (levantarse, ducharse, acostarse) e sentimentos (sentirse). O pronome vai antes do verbo conjugado ou colado no infinitivo/gerúndio. Alguns verbos mudam de sentido com o reflexivo (ir/irse, dormir/dormirse, poner/ponerse, quedar/quedarse).",
      briefReviewEn: "Reflexive verbs need pronouns: me/te/se/nos/os/se. Used for routines (levantarse, ducharse, acostarse) and feelings (sentirse). The pronoun goes before the conjugated verb or attached to the infinitive/gerund. Some verbs change meaning when reflexive (ir/irse, dormir/dormirse).",
