      briefReview: "SABER = informação/habilidade (sé nadar, sé que viene). CONOCER = experiência com pessoas/lugares (conozco a María, conozco Madrid). PEDIR = solicitar algo (pido un café). PREGUNTAR = fazer pergunta (pregunto la hora). LLEVAR (daqui pra lá) / TRAER (pra cá). IR (afastar) / VENIR (aproximar). PODER = possibilidade física / SABER = habilidade.",
