              "también (também): Yo también quiero ir.",
              "además (além disso): Es inteligente y, además, trabajador.",
              "incluso (até, inclusive): Incluso habla japonés.",
              "tampoco (tampouco — negativo): Yo tampoco sé. Ella tampoco viene.",
