      briefReview: "Conectores estruturam o discurso. Adição: y/e, también, además, incluso, tampoco. Contraste: pero, sin embargo, aunque, a pesar de, en cambio. Causa: porque, como, ya que. Consequência: por eso, así que, entonces, por lo tanto. Finalidade: para, para que. Tempo: cuando, mientras, antes/después de, luego. Organizadores: primero, luego, por un lado, en resumen, es decir, por ejemplo.",
