      titleEn: "Simple Future and Future Perfect",
      summary: "Forme o Futuro Simple (previsão, probabilidade) e o Futuro Compuesto (ação concluída antes de um momento futuro).",
      summaryEn: "Form the Simple Future (prediction, probability) and the Future Perfect (action completed before a future moment).",
